using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>Guards the layering: Domain <- Application <- Infrastructure, and no technical details in the business layers.</summary>
public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO",
        "System.Net",
        "System.Data",
        "System.Text.Json",
        "System.Diagnostics.Process",
        "Microsoft.Data",
        "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions.Http",
    ];

    private static Assembly Domain => typeof(Money).Assembly;
    private static Assembly Application => typeof(AuthorizePayment).Assembly;
    private static Assembly Infrastructure => typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_outer_layers() =>
        AssertNoViolation(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(ApplicationNs, InfrastructureNs));

    [Fact]
    public void Application_does_not_depend_on_infrastructure() =>
        AssertNoViolation(Types.InAssembly(Application).ShouldNot().HaveDependencyOn(InfrastructureNs));

    [Fact]
    public void Domain_does_not_use_technical_details() =>
        AssertNoViolation(Types.InAssembly(Domain).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Application_does_not_use_technical_details() =>
        AssertNoViolation(Types.InAssembly(Application).ShouldNot().HaveDependencyOnAny(TechnicalNamespaces));

    [Fact]
    public void Infrastructure_is_not_referenced_by_inner_assemblies()
    {
        Assert.DoesNotContain(Domain.GetReferencedAssemblies(), a => a.Name == Infrastructure.GetName().Name);
        Assert.DoesNotContain(Application.GetReferencedAssemblies(), a => a.Name == Infrastructure.GetName().Name);
    }

    private static void AssertNoViolation(ConditionList rule)
    {
        var result = rule.GetResult();
        Assert.True(result.IsSuccessful, "Layer violation in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
E
